//! Snapshot tests for the code generated by `#[sqlx_pg_test_template::test]`.
//!
//! Each test expands the attribute on a sample function and compares the pretty-printed
//! result with the snapshot stored in `snapshots/`. After changing the macro, accept the new
//! output with `cargo insta test -p sqlx-pg-test-template-macros --review` (or run the tests
//! with `INSTA_UPDATE=always`) and check the resulting diff.

use proc_macro2::TokenStream;
use quote::quote;

use crate::expand;

/// Expands the attribute and pretty-prints the result.
///
/// The first line echoes the attribute so that every snapshot is readable on its own.
/// Panics with the raw tokens if the output is not a valid Rust file, i.e. the macro
/// produced syntactically broken code.
fn expand_pretty(args: TokenStream, input: TokenStream) -> String {
    let output = expand(args.clone(), input);
    let file: syn::File = syn::parse2(output.clone()).unwrap_or_else(|err| {
        panic!("macro output is not a valid Rust file: {err}\n--- raw tokens ---\n{output}")
    });

    format!(
        "// #[sqlx_pg_test_template::test({args})]\n{}",
        prettyplease::unparse(&file)
    )
}

/// The function most tests apply the attribute to.
fn sample_fn() -> TokenStream {
    quote! {
        async fn my_test(pool: Pool<Postgres>) {}
    }
}

// --- attribute arguments ----------------------------------------------------

#[test]
fn default_args() {
    insta::assert_snapshot!(expand_pretty(quote!(), sample_fn()));
}

#[test]
fn template_arg() {
    insta::assert_snapshot!(expand_pretty(quote!(template = "my_template"), sample_fn()));
}

#[test]
fn max_connections_arg() {
    insta::assert_snapshot!(expand_pretty(quote!(max_connections = 5), sample_fn()));
}

#[test]
fn keep_db_on_failure_true() {
    insta::assert_snapshot!(expand_pretty(
        quote!(keep_db_on_failure = true),
        sample_fn()
    ));
}

#[test]
fn keep_db_on_failure_false() {
    insta::assert_snapshot!(expand_pretty(
        quote!(keep_db_on_failure = false),
        sample_fn()
    ));
}

#[test]
fn all_args() {
    insta::assert_snapshot!(expand_pretty(
        quote!(
            template = "my_template",
            max_connections = 3,
            keep_db_on_failure = true
        ),
        sample_fn()
    ));
}

#[test]
fn trailing_comma() {
    insta::assert_snapshot!(expand_pretty(
        quote!(template = "my_template",),
        sample_fn()
    ));
}

#[test]
fn duplicate_arg_last_wins() {
    insta::assert_snapshot!(expand_pretty(
        quote!(max_connections = 1, max_connections = 2),
        sample_fn()
    ));
}

// --- function shape ---------------------------------------------------------

#[test]
fn preserves_attributes_and_docs() {
    insta::assert_snapshot!(expand_pretty(
        quote!(),
        quote! {
            /// Documentation stays on the generated test.
            #[should_panic(expected = "boom")]
            async fn my_test(pool: Pool<Postgres>) {
                panic!("boom");
            }
        }
    ));
}

#[test]
fn explicit_return_type() {
    insta::assert_snapshot!(expand_pretty(
        quote!(),
        quote! {
            async fn my_test(pool: Pool<Postgres>) -> () {
                ()
            }
        }
    ));
}

/// The return type is copied to both the generated test and the inner async fn, so the runner
/// can pass a `Result` through to the test framework.
#[test]
fn result_return_type() {
    insta::assert_snapshot!(expand_pretty(
        quote!(),
        quote! {
            async fn my_test(pool: Pool<Postgres>) -> Result<(), sqlx::Error> {
                Ok(())
            }
        }
    ));
}

#[test]
fn custom_wrapper_arg() {
    insta::assert_snapshot!(expand_pretty(
        quote!(),
        quote! {
            async fn my_test(db: AppDb) {}
        }
    ));
}

#[test]
fn body_with_statements() {
    insta::assert_snapshot!(expand_pretty(
        quote!(),
        quote! {
            async fn my_test(pool: Pool<Postgres>) {
                let row: (i64,) = sqlx::query_as("SELECT 1").fetch_one(&pool).await.unwrap();
                assert_eq!(row.0, 1);
            }
        }
    ));
}

// --- rejected input ---------------------------------------------------------

#[test]
fn error_unknown_arg() {
    insta::assert_snapshot!(expand_pretty(quote!(foo = "x"), sample_fn()));
}

#[test]
fn error_path_only_arg() {
    insta::assert_snapshot!(expand_pretty(quote!(template), sample_fn()));
}

#[test]
fn error_list_arg() {
    insta::assert_snapshot!(expand_pretty(quote!(template("my_template")), sample_fn()));
}

#[test]
fn error_template_not_string() {
    insta::assert_snapshot!(expand_pretty(quote!(template = 5), sample_fn()));
}

#[test]
fn error_max_connections_not_int() {
    insta::assert_snapshot!(expand_pretty(quote!(max_connections = "5"), sample_fn()));
}

#[test]
fn error_max_connections_overflow() {
    insta::assert_snapshot!(expand_pretty(
        quote!(max_connections = 99999999999),
        sample_fn()
    ));
}

/// `-1` is parsed as a negative integer literal and rejected because it does not fit in a `u32`.
#[test]
fn error_max_connections_negative() {
    insta::assert_snapshot!(expand_pretty(quote!(max_connections = -1), sample_fn()));
}

#[test]
fn error_keep_db_not_bool() {
    insta::assert_snapshot!(expand_pretty(quote!(keep_db_on_failure = 1), sample_fn()));
}

#[test]
fn error_args_not_meta() {
    insta::assert_snapshot!(expand_pretty(quote!(5), sample_fn()));
}

/// The item is parsed before the arguments, so the bad arguments are never reached.
#[test]
fn error_input_not_fn() {
    insta::assert_snapshot!(expand_pretty(
        quote!(template = 5),
        quote!(
            struct Foo;
        )
    ));
}
